<?php
declare(strict_types=1);
function governanceCatalog():array {static $c;return $c??=json_decode(file_get_contents(__DIR__.'/governance-catalog.json'),true,32,JSON_THROW_ON_ERROR);}
function govDate(mixed $v,bool $optional=true):string {$v=studioText($v??'',10);if($optional&&$v==='')return '';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v)||!checkdate((int)substr($v,5,2),(int)substr($v,8,2),(int)substr($v,0,4)))fail(422,'Bitte ein gültiges Datum verwenden.');return $v;}
function govNumber(mixed $v,float $min,float $max,bool $nullable=false):int|float|null {if($nullable&&$v===null)return null;if((!is_int($v)&&!is_float($v))||!is_finite((float)$v)||$v<$min||$v>$max)fail(422,'Zahl außerhalb des zulässigen Bereichs.');return $v;}
function govScope(mixed $raw):array {$s=studioRecord($raw);$type=studioEnum($s['type']??null,['organization','system','store','flow']);return ['type'=>$type,'id'=>$type==='organization'?'':labName($s['id']??null)];}
function govUniqueRows(mixed $raw,int $limit):array {$rows=labList($raw??[],$limit);$ids=[];foreach($rows as $row){$r=studioRecord($row);$id=labName($r['id']??null);if(isset($ids[$id]))fail(422,'Doppelte Governance-ID.');$ids[$id]=true;}return $rows;}
function govOptionalId(mixed $v):string {return $v===''||$v===null?'':labName($v);}
function governanceValidate(mixed $raw):array {
 $c=studioRecord($raw);$source=studioText($c['landscape']??'',32);if($source!==''&&!preg_match('/^[a-f0-9]{32}$/D',$source))fail(422,'Ungültige Landschaftsreferenz.');
 $out=['schemaVersion'=>1,'organization'=>studioText($c['organization']??'',180),'landscape'=>$source,'readiness'=>studioText($c['readiness']??'',32),'sandbox'=>null,'stakeholders'=>[],'roles'=>[],'assignments'=>[],'quality'=>[],'rules'=>[],'lifecycles'=>[],'journeyLinks'=>[],'ai'=>['useCase'=>'','scope'=>'','answers'=>[]]];
 if($out['readiness']!==''&&!preg_match('/^[a-f0-9]{32}$/D',$out['readiness']))fail(422,'Ungültiger Readiness-Verweis.');
 if($source===''&&isset($c['sandbox']))$out['sandbox']=landscapeValidate($c['sandbox']);
 $people=[];foreach(govUniqueRows($c['stakeholders']??[],200) as $p){$id=labName($p['id']);$people[$id]=true;$out['stakeholders'][]=['id'=>$id,'name'=>labName($p['name']??null,180),'department'=>studioText($p['department']??'',180),'kind'=>studioEnum($p['kind']??'person',['person','team','external'])];}
 $roles=[];foreach(govUniqueRows($c['roles']??governanceCatalog()['roles'],100) as $r){$id=labName($r['id']);$roles[$id]=true;$out['roles'][]=['id'=>$id,'name'=>labName($r['name']??null,180),'purpose'=>studioText($r['purpose']??'',1500),'family'=>studioText($r['family']??'Eigene Rolle',100)];}
 $person=function($id)use($people){$id=govOptionalId($id);if($id!==''&&!isset($people[$id]))fail(422,'Stakeholder nicht vorhanden.');return $id;};
 $assignmentKeys=[];foreach(govUniqueRows($c['assignments']??[],1000) as $a){$role=labName($a['role']??null);if(!isset($roles[$role]))fail(422,'Governance-Rolle fehlt.');$v=['id'=>$a['id'],'role'=>$role,'stakeholder'=>$person($a['stakeholder']??''),'scope'=>govScope($a['scope']??null),'raci'=>studioEnum($a['raci']??null,['A','R','C','I']),'state'=>studioEnum($a['state']??'active',['active','planned']),'note'=>studioText($a['note']??'',1500)];if(!$v['stakeholder'])fail(422,'Zuerst einen Stakeholder wählen.');$key=json_encode([$v['role'],$v['stakeholder'],$v['scope'],$v['raci']]);if(isset($assignmentKeys[$key]))fail(422,'Diese Zuordnung besteht bereits.');$assignmentKeys[$key]=true;$out['assignments'][]=$v;}
 $dimensions=array_keys(governanceCatalog()['dimensions']);$pairs=[];
 foreach(govUniqueRows($c['quality']??[],600) as $q){$flow=labName($q['flow']??null);$dimension=studioEnum($q['dimension']??null,$dimensions);$key=$flow.'|'.$dimension;if(isset($pairs[$key]))fail(422,'Je Datenfluss und Dimension eine aktuelle Messung pflegen.');$pairs[$key]=true;
  $passed=govNumber($q['passed']??null,0,1e8,true);$total=govNumber($q['total']??null,0,1e8,true);if(($passed!==null&&!is_int($passed))||($total!==null&&!is_int($total)))fail(422,'Fallzahlen in ganzen Zahlen angeben.');if(($passed===null)!==($total===null)||($total!==null&&($total<=0||$passed>$total)))fail(422,'Messung als passende Anzahl von höchstens allen geprüften Fällen angeben.');
  $maxAge=govNumber($q['maxAgeDays']??30,0,3650);if(!is_int($maxAge))fail(422,'Aktualitätsgrenze in ganzen Tagen angeben.');
  $v=['id'=>$q['id'],'flow'=>$flow,'dimension'=>$dimension,'passed'=>$passed,'total'=>$total,'target'=>govNumber($q['target']??95,0,100),'suitability'=>studioEnum($q['suitability']??'unknown',['unknown','unfit','limited','fit']),'measuredOn'=>govDate($q['measuredOn']??''),'maxAgeDays'=>$maxAge,'method'=>studioText($q['method']??'',1500),'evidence'=>studioText($q['evidence']??'',3000),'note'=>studioText($q['note']??'',2000)];if($v['measuredOn']>gmdate('Y-m-d'))fail(422,'Eine Messung kann nicht in der Zukunft liegen.');$out['quality'][]=$v;
 }
 foreach(govUniqueRows($c['rules']??[],300) as $r){$v=['id'=>$r['id'],'title'=>labName($r['title']??null,180),'framework'=>studioEnum($r['framework']??'Internal',['Internal','GDPR','AI Act','DSA','DMA','NIS2']),'reference'=>studioText($r['reference']??'',1000),'scope'=>govScope($r['scope']??null),'control'=>studioEnum($r['control']??'manual',['manual','quality']),'dimension'=>studioEnum($r['dimension']??'completeness',$dimensions),'threshold'=>govNumber($r['threshold']??95,0,100),'applicability'=>studioEnum($r['applicability']??'unknown',['unknown','applies','excluded']),'reason'=>studioText($r['reason']??'',2000),'state'=>studioEnum($r['state']??'draft',['draft','approved','retired']),'owner'=>$person($r['owner']??''),'evidence'=>studioText($r['evidence']??'',3000),'reviewedOn'=>govDate($r['reviewedOn']??''),'nextReview'=>govDate($r['nextReview']??''),'test'=>studioEnum($r['test']??'unknown',['unknown','passed','failed']),'description'=>studioText($r['description']??'',3000)];
  if($v['control']==='quality'&&$v['scope']['type']!=='flow')fail(422,'Eine Qualitätskontrolle benötigt einen Datenfluss.');if($v['applicability']==='excluded'&&trim($v['reason'])==='')fail(422,'Nichtanwendbarkeit kurz begründen.');if($v['reviewedOn']>gmdate('Y-m-d'))fail(422,'Ein Prüfnachweis kann nicht in der Zukunft liegen.');if($v['test']==='passed'&&(!trim($v['evidence'])||!$v['reviewedOn']||!$v['owner']))fail(422,'Eine bestandene Prüfung benötigt Beleg, Datum und Zuständigkeit.');$out['rules'][]=$v;
 }
 foreach(govUniqueRows($c['lifecycles']??[],40) as $a){$v=['id'=>$a['id'],'name'=>labName($a['name']??null,180),'purpose'=>studioText($a['purpose']??'',2000),'sourceStore'=>govOptionalId($a['sourceStore']??''),'nameFromSource'=>$a['nameFromSource']??false,'flows'=>labList($a['flows']??[],300),'steps'=>[]];if(!is_bool($v['nameFromSource']))fail(422,'Namensübernahme als Ja/Nein angeben.');if($v['nameFromSource']&&!$v['sourceStore'])fail(422,'Ein abgeleiteter Name benötigt einen Ausgangsbestand.');foreach($v['flows'] as $id)labName($id);if(count(array_unique($v['flows']))!==count($v['flows']))fail(422,'Datenfluss doppelt gewählt.');
  foreach(govUniqueRows($a['steps']??[],200) as $s){$hold=$s['hold']??false;if(!is_bool($hold))fail(422,'Aufbewahrungssperre als Ja/Nein angeben.');$days=govNumber($s['retentionDays']??null,0,365000,true);if($days!==null&&!is_int($days))fail(422,'Frist in ganzen Tagen angeben.');$step=['id'=>$s['id'],'system'=>labName($s['system']??null),'action'=>studioEnum($s['action']??null,['collect','store','edit','use','share','archive','delete']),'owner'=>$person($s['owner']??''),'state'=>studioEnum($s['state']??'planned',['planned','implemented','verified']),'retentionDays'=>$days,'hold'=>$hold,'holdReason'=>studioText($s['holdReason']??'',2000),'evidence'=>studioText($s['evidence']??'',3000)];if($hold&&trim($step['holdReason'])==='')fail(422,'Einen Aufbewahrungsgrund angeben.');if($step['state']==='verified'&&(!$step['owner']||!trim($step['evidence'])))fail(422,'Belegte Lebenszyklusschritte benötigen Zuständigkeit und Nachweis.');$v['steps'][]=$step;}$out['lifecycles'][]=$v;
 }
 foreach(govUniqueRows($c['journeyLinks']??[],300) as $j){$v=['id'=>$j['id'],'journey'=>studioText($j['journey']??'',32),'stage'=>labName($j['stage']??null),'element'=>studioEnum($j['element']??'phase',['phase','touchpoint','action','goal','channel']),'flows'=>labList($j['flows']??[],100)];if(!preg_match('/^[a-f0-9]{32}$/D',$v['journey'])||!$v['flows'])fail(422,'Eine Journey-Zuordnung benötigt eine Journey und Datenflüsse.');foreach($v['flows'] as $id)labName($id);if(count(array_unique($v['flows']))!==count($v['flows']))fail(422,'Datenfluss doppelt gewählt.');$out['journeyLinks'][]=$v;}
 $ai=studioRecord($c['ai']??[]);$out['ai']['useCase']=studioText($ai['useCase']??'',1000);$out['ai']['scope']=studioText($ai['scope']??'Gesamte Organisation',500);$answers=studioRecord($ai['answers']??[]);$aiIds=array_column(governanceCatalog()['ai'],'id');if(array_diff(array_keys($answers),$aiIds))fail(422,'Unbekannte AI-Readiness-Frage.');foreach($answers as $key=>$a){$a=studioRecord($a);$out['ai']['answers'][$key]=['level'=>studioEnum($a['level']??'unknown',['unknown','none','planned','pilot','managed','proven']),'evidence'=>studioText($a['evidence']??'',2000),'reviewedOn'=>govDate($a['reviewedOn']??'')];if($out['ai']['answers'][$key]['level']==='proven'&&(!trim($out['ai']['answers'][$key]['evidence'])||!$out['ai']['answers'][$key]['reviewedOn']))fail(422,'Nachweisliche Wirksamkeit benötigt einen Beleg und ein Datum.');if($out['ai']['answers'][$key]['reviewedOn']>gmdate('Y-m-d'))fail(422,'Bewertungsdatum liegt in der Zukunft.');}
 return $out;
}
// Stable reference keys allow unrelated edits after source deletion/revocation, never new dangling links.
function governanceRefs(array $c):array {
 $refs=[];$add=function($key,$type,$id)use(&$refs){if($type!=='organization'&&$id!=='')$refs[$key]=[$type,$id];};
 foreach(['assignments','rules'] as $kind)foreach($c[$kind]??[] as $r)$add($kind.':'.$r['id'],$r['scope']['type'],$r['scope']['id']);
 foreach($c['quality']??[] as $r)$add('quality:'.$r['id'],'flow',$r['flow']);
 foreach($c['lifecycles']??[] as $a){$add('asset:'.$a['id'],'store',$a['sourceStore']);foreach($a['flows'] as $id)$add('asset:'.$a['id'].':flow:'.$id,'flow',$id);foreach($a['steps'] as $s)$add('asset:'.$a['id'].':step:'.$s['id'],'system',$s['system']);}
 foreach($c['journeyLinks']??[] as $j){$add('journey:'.$j['id'],'journey',$j['journey']);$refs['journey-stage:'.$j['id']]=['stage',$j['journey'].'|'.$j['stage']];foreach($j['flows'] as $id)$add('journey:'.$j['id'].':flow:'.$id,'flow',$id);}
 ksort($refs);return $refs;
}
function governanceSourceAccess(array $u,string $pid,array &$c,?array $old=null):void {
 if(($c['readiness']??'')!==''&&($old['readiness']??'')!==$c['readiness']){labAccess($u,$pid,'readiness');$readiness=one('SELECT id FROM lab_objects WHERE id=? AND project_id=? AND kind="readiness"',[$c['readiness'],$pid]);if(!$readiness)fail(422,'Readiness-Arbeit gehört nicht zu diesem Projekt.');}
 $source=null;$available=true;$same=$old&&($old['landscape']??'')===$c['landscape'];$before=$same?governanceRefs($old):[];
 if($c['landscape']!==''){try{labAccess($u,$pid,'landscape');$source=one('SELECT * FROM lab_objects WHERE id=? AND project_id=? AND kind="landscape"',[$c['landscape'],$pid]);if(!$source)throw new ApiError(422,'Landschaft nicht verfügbar.');$source=json_decode($source['content'],true);}catch(ApiError $e){$available=false;if(!$same)throw $e;}}
 else $source=$c['sandbox'];
 $valid=['system'=>array_column($source['systems']??[],'id'),'store'=>array_column($source['stores']??[],'id'),'flow'=>array_column($source['flows']??[],'id')];
 foreach(governanceRefs($c) as $key=>[$type,$id]){if(($before[$key]??null)===[$type,$id])continue;if(!$available)fail(403,'Neue Zuordnungen benötigen Zugriff auf die Landschaft.');if(isset($valid[$type])&&!in_array($id,$valid[$type],true))fail(422,'Das gewählte System, der Datenbestand oder Datenfluss fehlt.');if($type==='journey'||$type==='stage'){labAccess($u,$pid,'journey');$jid=$type==='stage'?explode('|',$id,2)[0]:$id;$j=one('SELECT content FROM lab_objects WHERE id=? AND project_id=? AND kind="journey"',[$jid,$pid]);if(!$j)fail(422,'Journey im Projekt nicht verfügbar.');$jc=json_decode($j['content'],true);if($type==='stage'&&!in_array(explode('|',$id,2)[1],array_column($jc['stages'],'id'),true))fail(422,'Journey-Phase nicht mehr vorhanden.');if(($jc['infrastructure']['landscape']??'')!==$c['landscape']||$c['landscape']==='')fail(422,'Die Journey benötigt dieselbe verknüpfte Landschaft.');}}
 // Source-owned titles come from authorized metadata, never a client-supplied alias.
 if($available&&$source){$stores=array_column($source['stores']??[],null,'id');foreach($c['lifecycles'] as &$asset)if(($asset['nameFromSource']??false)&&isset($stores[$asset['sourceStore']]))$asset['name']=$stores[$asset['sourceStore']]['name'];unset($asset);}

}
function governanceContext(array $u,array $d):array {
 $pid=textField($d,'project',32);labAccess($u,$pid,'governance');$landscapes=[];$journeys=[];$readiness=[];
 foreach(['landscape','journey','readiness'] as $kind){try{labAccess($u,$pid,$kind);foreach(all('SELECT id,name,version FROM lab_objects WHERE project_id=? AND kind=? ORDER BY name,id',[$pid,$kind]) as $o){$o['version']=(int)$o['version'];if($kind==='landscape')$landscapes[]=$o;elseif($kind==='readiness')$readiness[]=$o;else{$o['content']=labObject($u,$o['id'])['content'];$journeys[]=$o;}}}catch(ApiError){}}
 return ['landscapes'=>$landscapes,'journeys'=>$journeys,'readiness'=>$readiness];
}
function governanceOverlay(array $u,array $d):array {
 $pid=textField($d,'project',32);labAccess($u,$pid,'governance');$landscape=textField($d,'landscape',32,false);$journey=textField($d,'journey',32,false);
 if($journey){$j=labObject($u,$journey);if($j['project_id']!==$pid||$j['kind']!=='journey')fail(404,'Journey nicht gefunden.');$landscape=$j['content']['infrastructure']['landscape']??'';}
 if(!$landscape)return ['objects'=>[]];$source=labObject($u,$landscape);if($source['project_id']!==$pid||$source['kind']!=='landscape')fail(404,'Landschaft nicht gefunden.');
 $objects=[];foreach(all('SELECT id,content FROM lab_objects WHERE project_id=? AND kind="governance" ORDER BY name,id',[$pid]) as $row){$c=json_decode($row['content'],true);if(($c['landscape']??'')===$landscape)$objects[]=labObject($u,$row['id']);}
 return ['objects'=>$objects,'landscape'=>$source];
}
function landscapeJourneys(array $u,array $d):array {
 $pid=textField($d,'project',32);labAccess($u,$pid,'landscape');labAccess($u,$pid,'journey');$id=textField($d,'landscape',32);$l=labObject($u,$id);if($l['project_id']!==$pid||$l['kind']!=='landscape')fail(404,'Landschaft nicht gefunden.');$objects=[];foreach(all('SELECT id,content FROM lab_objects WHERE project_id=? AND kind="journey" ORDER BY name,id',[$pid]) as $r)if((json_decode($r['content'],true)['infrastructure']['landscape']??'')===$id)$objects[]=labObject($u,$r['id']);return ['objects'=>$objects];
}
